@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_container">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }

    [Parameter] public int TimeoutSeconds { get; set; } = 300;

    [Parameter] public EventCallback OnIdle { get; set; }

    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _container;
    private IJSObjectReference? _module;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/UserActivityTracker.razor.js");
            await _module.InvokeVoidAsync("initialize", _container, _dotNetRef, TimeoutSeconds * 1000);
        }
    }

    [JSInvokable]
    public async Task NotifyIdle()
    {
        await OnIdle.InvokeAsync();
    }

    [JSInvokable]
    public async Task NotifyActive()
    {
        await OnActive.InvokeAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("dispose");
            await _module.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

let timer = null;
let isIdle = false;
let dotNetRef = null;
let timeoutMs = 300000;
let container = null;
let events = ["mousemove", "keydown", "click", "scroll"];

function handleActivity() {
    if (timer !== null) {
        clearTimeout(timer);
    }

    if (isIdle) {
        isIdle = false;
        dotNetRef.invokeMethodAsync("NotifyActive");
    }

    timer = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("NotifyIdle");
    }, timeoutMs);
}

export function initialize(element, ref, timeout) {
    container = element;
    dotNetRef = ref;
    timeoutMs = timeout;
    isIdle = false;

    events.forEach(evt => container.addEventListener(evt, handleActivity, { passive: true }));

    timer = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("NotifyIdle");
    }, timeoutMs);
}

export function dispose() {
    if (timer !== null) {
        clearTimeout(timer);
        timer = null;
    }

    if (container) {
        events.forEach(evt => container.removeEventListener(evt, handleActivity));
        container = null;
    }

    dotNetRef = null;
    isIdle = false;
}

